if (!defined('ABSPATH')) exit;

add_action('template_redirect', function () {
    if (is_admin() || is_feed() || wp_doing_ajax()) return;
    $path = trailingslashit((string) wp_parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH));
    $pages = ddg_corporate_v2_pages();
    if (!isset($pages[$path])) return;
    $d = $pages[$path];
    status_header(200);
    get_header();
    echo '<main class="ddgcf ddg-corporate-v2"><section class="ddgcf-hero"><div><p class="ey">'.esc_html($d['ey']).'</p><h1>'.esc_html($d['h1']).'</h1><p class="lead">'.esc_html($d['lead']).'</p></div></section><article><div class="ddgcf-in">'.wp_kses_post($d['html']).'</div></article></main>';
    get_footer();
    exit;
}, -200);

add_filter('pre_get_document_title', function($title){
    $path=trailingslashit((string)wp_parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH));
    $p=ddg_corporate_v2_pages(); return isset($p[$path])?$p[$path]['seo']:$title;
}, 200);

